# This script plots, for each untreated sample (one row per sample), the average chromosome-arm CNV state per malignant subcompartment
# (left, panel E) and the cell-level CNV burden per subcompartment with Kruskal-Wallis and pairwise Wilcoxon tests (right, panel C)
# Original script written by Somnath Tagore; it uses the tables generated by the Wilms CNV script
# Run from the root of the repository: Rscript scripts/Fig_3/a.R

library(dplyr)
library(readr)
library(ggplot2)
library(ggpubr)
library(patchwork)

outdir_ = 'out/'
if(!dir.exists(outdir_)){ dir.create(outdir_, recursive = T) }     # create the output directory only if it does not already exist

keep_subcompartments = c('blastema', 'epithelium', 'stroma')
subcompartment_colors = c(blastema = '#E64B35', stroma = '#4DBBD5', epithelium = '#00A087')
cnv_limits = c(-2, 2)                                                    # same CNV scale as the original script
cnv_colors = c('#313695', '#74add1', '#f7f7f7', '#f46d43', '#a50026')
arm_levels = c(c(rbind(paste0(1:22, 'p'), paste0(1:22, 'q'))), 'Xp', 'Xq', 'Yp', 'Yq')     # chromosome arm order

# STEP 1: Reading in CNV tables ####

avg_cnv = read_tsv('data/Misc/ALL_samples_average_CNV_by_state_arm.tsv', show_col_types = F) %>%
          mutate(sample = as.character(sample),
                 subcompartment = factor(subcompartment, levels = keep_subcompartments),
                 chrom_arm = factor(chrom_arm, levels = arm_levels, ordered = T))
arm_stats = read_tsv('data/Misc/ALL_samples_samplewise_arm_level_stats.tsv', show_col_types = F) %>%
            mutate(sample = as.character(sample),
                   chrom_arm = factor(as.character(chrom_arm), levels = arm_levels, ordered = T))
meta = read_tsv('data/Misc/ALL_samples_cell_level_CNV_metadata.tsv', show_col_types = F) %>%
       mutate(sample = as.character(sample),
              subcompartment = factor(subcompartment, levels = keep_subcompartments))

# STEP 2: Untreated samples ####

samples_use = c('W612', 'W340', 'W011', 'W132', 'W495', 'W008', 'W007', 'W005', 'W004', 'W241', 'W040', 'W012')
samples_use = samples_use[samples_use %in% unique(avg_cnv$sample) & samples_use %in% unique(meta$sample)]     # samples present in the data

# STEP 3: Plotting ####

## step 3.1: panel E for one sample: average CNV per chromosome arm and subcompartment, with significance of arm-level tests ####

make_panel_E = function(sample_id, show_legend = F)     # legend shown only for the last sample
{
  df_ = avg_cnv %>% filter(sample == sample_id)
  sig_df = arm_stats %>%
           filter(sample == sample_id) %>%
           mutate(signif_clean = case_when(is.na(signif) ~ '', signif == 'ns' ~ '', TRUE ~ signif)) %>%
           filter(signif_clean != '')

  ggplot(df_, aes(x = chrom_arm, y = subcompartment, fill = mean_cnv))+
    geom_tile(color = 'black', linewidth = 0.15)+
    geom_text(data = sig_df, aes(x = chrom_arm, y = keep_subcompartments[1], label = signif_clean), inherit.aes = F, size = 2.2, fontface = 'bold', vjust = -0.15)+
    scale_fill_gradientn(colors = cnv_colors, limits = cnv_limits, oob = scales::squish, name = 'Mean CNV',
                         breaks = c(-2, -1, 0, 1, 2), labels = c('bdel', 'del', 'neu', 'amp', 'bamp'))+
    scale_y_discrete(drop = F)+
    scale_x_discrete(drop = F)+
    labs(title = sample_id, x = NULL, y = NULL)+
    theme_bw(base_size = 8)+
    theme(plot.title = element_text(size = 9, face = 'bold', hjust = 0, margin = margin(b = 2)),
          axis.text.x = element_text(size = 5, angle = 90, vjust = 0.5, hjust = 1),
          axis.text.y = element_text(size = 7),
          axis.ticks = element_blank(),
          panel.grid = element_blank(),
          legend.position = if(show_legend){ 'bottom' }else{ 'none' },
          legend.direction = 'horizontal',
          legend.title.position = 'top',
          legend.key.width = unit(1.2, 'cm'),
          legend.key.height = unit(0.25, 'cm'),
          legend.title = element_text(size = 7),
          legend.text = element_text(size = 6),
          plot.margin = margin(2, 4, 2, 2))
}

## step 3.2: panel C for one sample: cell-level CNV burden per subcompartment ####

make_panel_C = function(sample_id, show_legend = F)     # legend shown only for the last sample
{
  df_ = meta %>% filter(sample == sample_id, !is.na(cnv_burden_main), !is.na(subcompartment))
  kw_ = tryCatch(kruskal.test(cnv_burden_main ~ subcompartment, data = df_), error = function(e){ NULL })     # NULL if fewer than 2 subcompartments
  kw_label = if(!is.null(kw_)){ paste0('KW P = ', signif(kw_$p.value, 3)) }else{ 'KW P = NA' }

  p_ = ggplot(df_, aes(x = subcompartment, y = cnv_burden_main))+
    geom_violin(aes(fill = subcompartment), color = 'black', trim = F, linewidth = 0.25, alpha = 0.8)+
    geom_boxplot(width = 0.14, outlier.shape = NA, fill = 'white', color = 'black', linewidth = 0.25)+
    scale_fill_manual(values = subcompartment_colors, drop = F, name = 'Subcompartment')+
    labs(title = kw_label, x = NULL, y = 'CNV burden')+
    theme_bw(base_size = 8)+
    theme(plot.title = element_text(size = 8, face = 'bold', hjust = 0.5),
          axis.text.x = element_text(size = 6, angle = 30, hjust = 1),
          axis.text.y = element_text(size = 6),
          axis.title.y = element_text(size = 7),
          legend.position = if(show_legend){ 'bottom' }else{ 'none' },
          legend.direction = 'horizontal',
          legend.title.position = 'top',
          legend.key.size = unit(0.3, 'cm'),
          legend.title = element_text(size = 7),
          legend.text = element_text(size = 6),
          panel.grid = element_blank(),
          plot.margin = margin(2, 2, 2, 4))
  if(2 <= length(unique(df_$subcompartment)))
  {
    p_ = p_ + stat_compare_means(comparisons = list(c('blastema', 'epithelium'), c('blastema', 'stroma'), c('epithelium', 'stroma')),
                                 method = 'wilcox.test', label = 'p.format', hide.ns = F, size = 2.0, tip.length = 0.01)
  }
  p_
}

## step 3.3: one row per sample (panel E left, panel C right), all samples stacked ####

sample_rows = lapply(samples_use, function(sid_)
{
  last_ = sid_ == tail(samples_use, 1)     # only the last sample shows the legends
  make_panel_E(sid_, show_legend = last_) + make_panel_C(sid_, show_legend = last_) + plot_layout(widths = c(3.4, 1.15))
})
final_plot = wrap_plots(sample_rows, ncol = 1)+
  plot_annotation(title = 'Sample-resolved CNV architecture and CNV burden across Wilms tumor subcompartments',
                  subtitle = 'Left: average chromosome-arm CNV state by subcompartment. Right: cell-level CNV burden with sample-wise statistics.',
                  theme = theme(plot.title = element_text(size = 13, face = 'bold'), plot.subtitle = element_text(size = 9)))

## step 3.4: saving ####

ggsave(filename = file.path(outdir_, 'Wilms_UNTREATED_compact_PanelE_left_PanelC_right.pdf'), plot = final_plot, width = 18, height = 29, units = 'in', device = 'pdf')
ggsave(filename = file.path(outdir_, 'Wilms_UNTREATED_compact_PanelE_left_PanelC_right.png'), plot = final_plot, width = 18, height = 29, units = 'in', dpi = 300, device = 'png')
rm(avg_cnv, arm_stats, meta, sample_rows, final_plot); gc()
